function buildQuoteEvents() {
  const t0    = 1774040404000;
  const tEnd  = 1774126783000;
  const events = RAW_QUOTES.map(q => ({
    id:              'quote_' + q.id,
    type:            'quote',
    timestamp:       q.ts,
    customerLat:     q.customerLat,
    customerLng:     q.customerLng,
    proLat:          q.proLat,
    proLng:          q.proLng,
    serviceName:     q.service,
    serviceCategory: q.cat,
    arcDuration:     1500,
    arcFadeDelay:    0,
  }));
  return { events, simStart: t0, simEnd: tEnd };
}

const _quotes = buildQuoteEvents();
export const ISTANBUL_QUOTE_EVENTS    = _quotes.events;
export const ISTANBUL_QUOTE_SIM_START = _quotes.simStart;
export const ISTANBUL_QUOTE_SIM_END   = _quotes.simEnd;
